WITH order_totals AS (SELECT order_id, COUNT(DISTINCT unit_price) AS unique_products, ROUND(AVG(quantity), 2) AS avg_quantity FROM order_items GROUP BY order_id) SELECT o.store_id, ot.unique_products, ot.avg_quantity FROM orders o JOIN order_totals ot ON o.id = ot.order_id WHERE ot.unique_products > 5
